CREATE DATABASE IF NOT EXISTS learn_afghan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE learn_afghan;
CREATE TABLE IF NOT EXISTS zones (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS branches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,zone_id INT UNSIGNED NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,location VARCHAR(250),status ENUM('active','inactive','pending') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(zone_id) REFERENCES zones(id));
CREATE TABLE IF NOT EXISTS departments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(45) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,parent_id INT UNSIGNED NULL,FOREIGN KEY(parent_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,display_name VARCHAR(180) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','zone_admin','branch_admin','department_user') NOT NULL,zone_id INT UNSIGNED NULL,branch_id INT UNSIGNED NULL,department_id INT UNSIGNED NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(zone_id) REFERENCES zones(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(60) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id VARCHAR(80) NULL,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_audit_time(created_at));
-- No invented real-world branch/user records are seeded.